template:
{%- macro action(a, label, class) -%}
{%- if a.method in ("POST", "PUT", "PATCH", "DELETE") -%}
<button type="button" class="{{ class }}" hx-{{ a.method|lower }}="{{ in_mount(a.href) }}" hx-ext="scrud-json" hx-swap="none" data-scrud-json="fixed" data-scrud-body='{{ a.body|tojson }}' data-scrud-etag="{{ a.etag or '' }}">{{ label }}</button>
{%- endif -%}
{%- endmacro -%}
{%- macro entry(item) -%}
{%- set open = {"kind": item.kind, "name": item.name, "applies_to": item.get("applies_to"), "href": in_mount(item.href) if item.href else none, "override": item.override, "reverts_to": item.get("reverts_to")} %}
<li class="studio-item studio-{{ item.origin }}{% if item.conflict %} studio-conflict-{{ item.conflict }}{% endif %}">
<button type="button" class="studio-open" data-studio-open='{{ open|tojson }}'>{{ item.name }}{% if item.get("applies_to") %} <span class="studio-applies-to">({{ item.applies_to }})</span>{% endif %}</button>
<span class="studio-origin">{% if item.origin == "own" %}own{% elif item.origin == "inherited" %}from {{ item["from"] }}{% else %}packaged{% endif %}</span>
{%- if item.conflict %} <span class="studio-conflict">conflict with the {{ item.conflict }}</span>{% endif %}
{%- if item.href is none %}
<pre data-studio-content hidden>{{ item.content|tojson(indent=2) }}</pre>
{%- endif %}
{%- if item.override %}
{{ action(item.override, "Override on this branch", "studio-override") }}
{%- endif %}
</li>
{%- endmacro -%}
{%- set kinds = [("component", "Components"), ("stylesheet", "Stylesheets"), ("css", "CSS"), ("js", "JavaScript")] -%}
<nav class="studio-items" aria-label="Items of {{ value.branch }}">
{%- for kind, heading in kinds %}
{%- set entries = value["items"]|selectattr("kind", "equalto", kind)|list %}
{%- if entries %}
{%- set mine = entries|rejectattr("origin", "equalto", "packaged")|list %}
{%- set packaged = entries|selectattr("origin", "equalto", "packaged")|list %}
<section class="studio-kind" data-studio-kind="{{ kind }}">
<h3 class="studio-kind-title">{{ heading }}</h3>
{%- if mine %}
<ul class="studio-kind-items">
{%- for item in mine %}
{{ entry(item) }}
{%- endfor %}
</ul>
{%- endif %}
{%- if packaged %}
<details class="studio-packaged-group" data-studio-packaged>
<summary>Packaged ({{ packaged|length }})</summary>
<ul class="studio-kind-items">
{%- for item in packaged %}
{{ entry(item) }}
{%- endfor %}
</ul>
</details>
{%- endif %}
</section>
{%- endif %}
{%- endfor %}
</nav>
